"use client";
/* Keycap, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Keycap(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("keycap"); }, []);
  return React.createElement("piix-sprite", { "name": "keycap", ...piixAttrs(props) });
}

export default Keycap;
